import React, { useState } from 'react';

function Admin({ menuItems, setMenuItems, allOrders }) {
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    price: '',
    image: '',
    category: ''
  });

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleAddItem = (e) => {
    e.preventDefault();
    const newItem = {
      id: menuItems.length + 1,
      name: formData.name,
      price: parseInt(formData.price),
      image: formData.image,
      category: formData.category
    };
    setMenuItems([...menuItems, newItem]);
    setFormData({ name: '', price: '', image: '', category: '' });
    setShowAddForm(false);
    alert('Item added successfully!');
  };

  const handleUpdateItem = (e) => {
    e.preventDefault();
    setMenuItems(menuItems.map(item => 
      item.id === editingItem.id 
        ? { ...item, name: formData.name, price: parseInt(formData.price), image: formData.image, category: formData.category }
        : item
    ));
    setEditingItem(null);
    setFormData({ name: '', price: '', image: '', category: '' });
    alert('Item updated successfully!');
  };

  const handleDeleteItem = (id) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      setMenuItems(menuItems.filter(item => item.id !== id));
      alert('Item deleted successfully!');
    }
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({
      name: item.name,
      price: item.price.toString(),
      image: item.image,
      category: item.category
    });
    setShowAddForm(false);
  };

  const cancelEdit = () => {
    setEditingItem(null);
    setFormData({ name: '', price: '', image: '', category: '' });
  };

  const totalRevenue = allOrders.reduce((sum, order) => sum + order.total, 0);
  const totalOrders = allOrders.length;

  return (
    <div className="admin-container">
      <h1 style={{ textAlign: 'center', marginBottom: '30px', color: '#333' }}>Admin Dashboard</h1>

      {/* Stats Overview */}
      <div className="admin-stats">
        <div className="stat-card">
          <h3>Total Items</h3>
          <p className="stat-value">{menuItems.length}</p>
        </div>
        <div className="stat-card">
          <h3>Total Orders</h3>
          <p className="stat-value">{totalOrders}</p>
        </div>
        <div className="stat-card">
          <h3>Total Revenue</h3>
          <p className="stat-value">₹{totalRevenue}</p>
        </div>
      </div>

      {/* Add Item Button */}
      <div style={{ textAlign: 'center', margin: '30px 0' }}>
        <button 
          className="btn" 
          onClick={() => {
            setShowAddForm(!showAddForm);
            setEditingItem(null);
            setFormData({ name: '', price: '', image: '', category: '' });
          }}
        >
          {showAddForm ? 'Cancel' : '+ Add New Item'}
        </button>
      </div>

      {/* Add/Edit Form */}
      {(showAddForm || editingItem) && (
        <div className="admin-form-container">
          <h3>{editingItem ? 'Edit Item' : 'Add New Item'}</h3>
          <form onSubmit={editingItem ? handleUpdateItem : handleAddItem}>
            <div className="form-group">
              <label>Item Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Price (₹)</label>
              <input
                type="number"
                name="price"
                value={formData.price}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Image URL</label>
              <input
                type="url"
                name="image"
                value={formData.image}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Category</label>
              <select
                name="category"
                value={formData.category}
                onChange={handleInputChange}
                required
              >
                <option value="">Select Category</option>
                <option value="Meals">Meals</option>
                <option value="Snacks">Snacks</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Beverages">Beverages</option>
                <option value="South Indian">South Indian</option>
                <option value="Street Food">Street Food</option>
              </select>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <button type="submit" className="btn">
                {editingItem ? 'Update Item' : 'Add Item'}
              </button>
              {editingItem && (
                <button type="button" className="btn btn-danger" onClick={cancelEdit}>
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>
      )}

      {/* Menu Items List */}
      <div className="admin-items-list">
        <h3>Menu Items</h3>
        <div className="admin-table">
          {menuItems.map(item => (
            <div key={item.id} className="admin-item-row">
              <img src={item.image} alt={item.name} className="admin-item-img" />
              <div className="admin-item-info">
                <h4>{item.name}</h4>
                <p>₹{item.price} | {item.category}</p>
              </div>
              <div className="admin-item-actions">
                <button className="btn-edit" onClick={() => startEdit(item)}>
                  ✏️ Edit
                </button>
                <button className="btn-delete" onClick={() => handleDeleteItem(item.id)}>
                  🗑️ Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Admin;
